CREATE TABLE IF NOT EXISTS notification_templates (template_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NULL, template_code TEXT NOT NULL, channel TEXT NOT NULL, subject_template TEXT NULL, body_template TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,template_code,channel));
CREATE TABLE IF NOT EXISTS notifications (notification_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NULL, location_id TEXT NULL, recipient_user_id TEXT NULL, recipient_address TEXT NULL, template_id TEXT NULL, channel TEXT NOT NULL, subject TEXT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', related_type TEXT NULL, related_id TEXT NULL, scheduled_at TEXT NULL, sent_at TEXT NULL, failure_reason TEXT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approval_workflows (workflow_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NULL, workflow_code TEXT NOT NULL, workflow_name TEXT NOT NULL, module_name TEXT NOT NULL, min_amount REAL NULL, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,workflow_code));
CREATE TABLE IF NOT EXISTS approval_requests (approval_request_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NULL, location_id TEXT NULL, workflow_id TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, requested_by TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_by TEXT NULL, decided_at TEXT NULL, decision_reason TEXT NULL, payload_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS approval_steps (step_id TEXT PRIMARY KEY, approval_request_id TEXT NOT NULL, step_no INTEGER NOT NULL, approver_user_id TEXT NULL, approver_role_id TEXT NULL, status TEXT NOT NULL DEFAULT 'PENDING', decided_by TEXT NULL, decided_at TEXT NULL, decision_reason TEXT NULL, UNIQUE(approval_request_id,step_no));
CREATE INDEX IF NOT EXISTS ix_notifications_queue ON notifications(status,scheduled_at,created_at);
CREATE INDEX IF NOT EXISTS ix_approval_queue ON approval_requests(organization_id,entity_id,status,requested_at);
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('notification.view','View notifications') ON CONFLICT DO NOTHING;
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('notification.send','Create/send notifications') ON CONFLICT DO NOTHING;
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('approval.view','View approval queue') ON CONFLICT DO NOTHING;
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('approval.submit','Submit approvals') ON CONFLICT DO NOTHING;
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('approval.decide','Approve/reject workflow requests') ON CONFLICT DO NOTHING;
INSERT INTO erp_permissions(permission_id,permission_name) VALUES('approval.manage','Manage approval workflows') ON CONFLICT DO NOTHING;
